     * both registerNew(renewal) and registerNew(task, WhatId, renewal), the
     * related object IS the same instance. We verify this by checking that
     * the "related" SObject is not the original opportunity (different Name
     * would suffice, but same-instance is stronger).
     */
    private static Boolean referenceEquals(SObject a, SObject b) {
        if (a == null || b == null) return a == b;
        // In Apex, the == operator on SObject does reference comparison
        // when both sides are SObject (not Id).
        return a == b;
    }
