```apex
public class Opportunities extends fflib_SObjectDomain {

    public Opportunities(List<SObject> sobjs, Map<Id, SObject> previousValues) {
        super(sobjs, previousValues);
    }

    public class Constructor extends fflib_SObjectDomain.Constructor {
        public Constructor() {
            super(new Opportunities(null, null));
        }
    }

    protected override void validateInsert() {
        for (Opportunity opp : (List<Opportunity>) getSobjs()) {
            if (opp.Amount != null && opp.Amount < 0) {
                error('Amount cannot be negative.', opp, Opportunity.Amount);
            }
        }
    }

    protected override void validateUpdate() {
        Map<Id, SObject> prevMap = getPreviousValues();
        for (Opportunity opp : (List<Opportunity>) getSobjs()) {
            // Rule 1: Amount must not be negative
            if (opp.Amount != null && opp.Amount < 0) {
                error('Amount cannot be negative.', opp, Opportunity.Amount);
            }

            // Rule 2: Amount cannot change on an opportunity already Closed Won
            Opportunity prev = (Opportunity) prevMap.get(opp.Id);
            if (prev != null && prev.StageName == 'Closed Won') {
                if (opp.Amount != prev.Amount) {
                    error('Amount cannot change on a won opportunity.', opp, Opportunity.Amount);
                }
            }
        }
    }
}
```

