import { LightningElement } from 'lwc';
import getQueueStats from '@salesforce/apex/QueueController.getQueueStats';

const POLL_INTERVAL_MS = 60000;

export default class QueueMonitor extends LightningElement {
    waiting = 0;
    longestWaitMinutes = 0;
    error = null;
    hasStats = false;

    _intervalId = null;
    _isInFlight = false;
    _visibilityHandler = null;
    _generation = 0;

    connectedCallback() {
        this._generation++;
        const gen = this._generation;

        this._visibilityHandler = this._handleVisibilityChange.bind(this);
        document.addEventListener('visibilitychange', this._visibilityHandler);

        this._loadStats(gen);
        this._intervalId = setInterval(() => {
            if (this._generation === gen) {
                this._loadStats(gen);
            }
        }, POLL_INTERVAL_MS);
    }

    disconnectedCallback() {
        this._generation++;

        if (this._intervalId !== null) {
            clearInterval(this._intervalId);
            this._intervalId = null;
        }

        if (this._visibilityHandler) {
            document.removeEventListener('visibilitychange', this._visibilityHandler);
            this._visibilityHandler = null;
        }

        this._isInFlight = false;
    }

    _handleVisibilityChange() {
        if (document.visibilityState === 'visible') {
            this._loadStats(this._generation);
        }
    }

    _loadStats(gen) {
        if (this._isInFlight) {
            return;
        }
        if (document.visibilityState === 'hidden') {
            return;
        }

        this._isInFlight = true;

        getQueueStats()
            .then((result) => {
                if (gen !== this._generation) return;
                this.waiting = result.waiting;
                this.longestWaitMinutes = result.longestWaitMinutes;
                this.hasStats = true;
                this.error = null;
            })
            .catch((err) => {
                if (gen !== this._generation) return;
                this.error = err.body.message;
            })
            .finally(() => {
                if (gen !== this._generation) return;
                this._isInFlight = false;
            });
    }
}
