public with sharing class EmployerService {

    /**
     * Sets the current employer (Organization) for a batch of contacts using NPSP Affiliations.
     * 
     * For each Contact:Id -> Organization:Id pair in the input map:
     *   - Creates or promotes a primary, Current affiliation to the target Organization.
     *   - NPSP's standard trigger on NPE01__Affiliation__c handles demoting the previous
     *     primary to Former with today's end date, and updating the Contact's
     *     NPE01__PrimaryAffiliation__c lookup.
     *   - If the target Organization is already the contact's current primary affiliation,
     *     no change is made (no duplicate).
     * 
     * Governor limits: 1 SOQL query, at most 2 DML statements (insert + update).
     * 
     * @param employerByContactId  Map of Contact Id -> Organization Account Id.
     */
    public static void setCurrentEmployers(Map<Id, Id> employerByContactId) {
        if (employerByContactId == null || employerByContactId.isEmpty()) {
            return;
        }

        Set<Id> contactIds = employerByContactId.keySet();

        // ─── SOQL 1 (only): fetch all existing affiliations for the target contacts ───
        Map<Id, List<NPE01__Affiliation__c>> affiliationsByContactId =
            new Map<Id, List<NPE01__Affiliation__c>>();

        for (NPE01__Affiliation__c aff : [
            SELECT Id,
                   NPE01__Contact__c,
                   NPE01__Account__c,
                   NPE01__IsPrimary__c,
                   NPE01__Status__c,
                   NPE01__EndDate__c
            FROM NPE01__Affiliation__c
            WHERE NPE01__Contact__c IN :contactIds
        ]) {
            affiliationsByContactId
                .getOrDefault(aff.NPE01__Contact__c, new List<NPE01__Affiliation__c>())
                .add(aff);
        }

        List<NPE01__Affiliation__c> toInsert = new List<NPE01__Affiliation__c>();
        List<NPE01__Affiliation__c> toUpdate = new List<NPE01__Affiliation__c>();

        for (Id contactId : contactIds) {
            Id orgId = employerByContactId.get(contactId);
            if (orgId == null) {
                continue;
            }

            List<NPE01__Affiliation__c> contactAffs = affiliationsByContactId.get(contactId);

            NPE01__Affiliation__c currentPrimary = null;
            NPE01__Affiliation__c existingOrgAff = null;

            if (contactAffs != null) {
                for (NPE01__Affiliation__c aff : contactAffs) {
                    if (aff.NPE01__IsPrimary__c && aff.NPE01__Status__c == 'Current') {
                        currentPrimary = aff;
                    }
                    if (aff.NPE01__Account__c == orgId && existingOrgAff == null) {
                        existingOrgAff = aff;
                    }
                }
            }

            // If the target org is already the contact's current primary, skip entirely
            if (currentPrimary != null && currentPrimary.NPE01__Account__c == orgId) {
                continue;
            }

            if (existingOrgAff != null) {
                // Affiliation to this org exists but is not (current) primary – promote it
                existingOrgAff.NPE01__IsPrimary__c = true;
                existingOrgAff.NPE01__Status__c = 'Current';
                existingOrgAff.NPE01__EndDate__c = null;
                toUpdate.add(existingOrgAff);
            } else {
                // No affiliation to this org – create a new primary one
                toInsert.add(new NPE01__Affiliation__c(
                    NPE01__Contact__c  = contactId,
                    NPE01__Account__c  = orgId,
                    NPE01__IsPrimary__c = true,
                    NPE01__Status__c   = 'Current',
                    NPE01__Type__c     = 'Employer'
                ));
            }
        }

        // ─── DML 1: insert new primary affiliations ───
        // NPSP's NPE01__AffiliationTrigger will:
        //   • demote the previous primary to Former (end date = today)
        //   • set this one to Current
        //   • update the Contact.NPE01__PrimaryAffiliation__c lookup
        if (!toInsert.isEmpty()) {
            insert toInsert;
        }

        // ─── DML 2: update existing affiliations to primary ───
        // Same NPSP trigger logic applies on update.
        if (!toUpdate.isEmpty()) {
            update toUpdate;
        }
    }
}
