public class GiftImportService {

    public class WebGift {
        public String firstName;
        public String lastName;
        public String email;
        public Decimal amount;
        public Date giftDate;
    }

    public class ImportResult {
        public Boolean success;
        public Id contactId;
        public Id opportunityId;
        public String errorMessage;
    }

    public static List<ImportResult> importGifts(List<WebGift> gifts) {
        if (gifts == null || gifts.isEmpty()) {
            return new List<ImportResult>();
        }

        // Stage one OpportunityImport__c per gift
        List<Npe01__OpportunityImport__c> importRecords = new List<Npe01__OpportunityImport__c>();
        for (WebGift gift : gifts) {
            importRecords.add(new Npe01__OpportunityImport__c(
                Npe01__First_Name__c = gift.firstName,
                Npe01__Last_Name__c = gift.lastName,
                Npe01__Email__c = gift.email,
                Npe01__Amount__c = gift.amount,
                Npe01__Donated__c = gift.giftDate,
                Npe01__Opportunity_Type__c = 'Donation',
                Npe01__Status__c = 'Pending'
            ));
        }

        insert importRecords;

        // Process via NPSP Data Import API
        Set<Id> importIds = new Set<Id>();
        for (Npe01__OpportunityImport__c rec : importRecords) {
            importIds.add(rec.Id);
        }
        Npe01_DataImport.processImport(importIds);

        // Query back processed records
        Map<Id, Npe01__OpportunityImport__c> resultMap = new Map<Id, Npe01__OpportunityImport__c>(
            [SELECT Id, Npe01__Status__c, Npe01__Error_Message__c, 
                    Npe01__Contact__c, Npe01__Opportunity__c
             FROM Npe01__OpportunityImport__c 
             WHERE Id IN :importIds]
        );

        // Build results in input order
        List<ImportResult> results = new List<ImportResult>();
        for (Npe01__OpportunityImport__c rec : importRecords) {
            ImportResult ir = new ImportResult();
            Npe01__OpportunityImport__c processed = resultMap.get(rec.Id);
            if (processed != null) {
                ir.success = 'Processed'.equals(processed.Npe01__Status__c);
                ir.contactId = processed.Npe01__Contact__c;
                ir.opportunityId = processed.Npe01__Opportunity__c;
                ir.errorMessage = ir.success ? null : processed.Npe01__Error_Message__c;
            } else {
                ir.success = false;
                ir.errorMessage = 'Import record not found after processing';
            }
            results.add(ir);
        }

        return results;
    }
}
