public class RecurringGiftService {

    public class RecurringGiftException extends Exception {}

    public class GiftRequest {
        public Id contactId;
        public Decimal amount;
        public Integer dayOfMonth;
        public Date startDate;
        public Integer installments;
        public String paymentMethod;
    }

    // NPSP Enhanced Recurring Donations picklist value representing "last day of month"
    private static final String LAST_DAY_OF_MONTH = '31';

    public static List<Id> createMonthlyGifts(List<GiftRequest> requests) {
        if (requests == null || requests.isEmpty()) {
            return new List<Id>();
        }

        // Validate all requests before any DML
        for (GiftRequest req : requests) {
            if (req == null) {
                throw new RecurringGiftException('Gift request cannot be null.');
            }
            if (req.contactId == null) {
                throw new RecurringGiftException('Contact ID is required.');
            }
            if (req.amount == null || req.amount <= 0) {
                throw new RecurringGiftException('Amount must be a positive number.');
            }
            if (req.dayOfMonth == null || req.dayOfMonth < 1 || req.dayOfMonth > 31) {
                throw new RecurringGiftException('Day of month must be between 1 and 31.');
            }
            if (req.startDate == null) {
                throw new RecurringGiftException('Start date is required.');
            }
        }

        // Build recurring donation records
        List<npe03__Recurring_Donation__c> rds = new List<npe03__Recurring_Donation__c>();

        for (GiftRequest req : requests) {
            npe03__Recurring_Donation__c rd = new npe03__Recurring_Donation__c(
                npe03__Contact__c        = req.contactId,
                npe03__Amount__c         = req.amount,
                npe03__Start_Date__c     = req.startDate,
                npe03__Installments__c   = (req.installments == null || req.installments == 0) ? null : req.installments,
                npe03__Status__c         = 'Active',
                npe03__Payment_Method__c = req.paymentMethod,
                npe03__Frequency__c      = 'Monthly',
                npe03__Interval__c       = 1,
                npe03__Day_of_Month__c   = (req.dayOfMonth == 31) ? LAST_DAY_OF_MONTH : String.valueOf(req.dayOfMonth)
            );
            rds.add(rd);
        }

        // Single DML statement for bulk safety
        insert rds;

        // Return new Ids in request order
        List<Id> ids = new List<Id>(rds.size());
        for (npe03__Recurring_Donation__c rd : rds) {
            ids.add(rd.Id);
        }
        return ids;
    }
}
```

**Key design decisions:**

| Concern | Approach |
|---|---|
| **Bulk safety** | All validation happens in a loop with zero governor consumption; a single `insert` handles up to 200 records; no SOQL queries are issued at all. |
| **All-or-nothing** | Validation of *every* request completes before the single DML statement, so no partial inserts occur on failure. |
| **Last day of month** | `dayOfMonth == 31` maps to NPSP's own last-day-of-month picklist value (`'31'`); values 1–30 are stored as their literal string equivalents. |
| **Open-ended vs fixed** | `installments` of `null` or `0` → `npe03__Installments__c` is set to `null` (open-ended); any positive integer is passed through as the planned installment count. |
| **No Opportunity creation** | The method only creates `npe03__Recurring_Donation__c` records; NPSP's native automation (flow / trigger) handles generating the installment Opportunities. |
| **Return order** | The `insert` preserves list order, so the returned Id list matches the input request order. |

