public class SoftCreditService {

    public class SoftCreditException extends Exception {}

    public class SoftCreditRequest {
        public Id opportunityId;
        public Id contactId;
        public Decimal amount;
        public String role;
    }

    public static void addPartialSoftCredits(List<SoftCreditRequest> requests) {
        if (requests == null || requests.isEmpty()) {
            return;
        }

        // Collect unique opportunity IDs and pair keys for lookup
        Set<Id> oppIds = new Set<Id>();
        Set<String> pairKeys = new Set<String>();

        for (SoftCreditRequest req : requests) {
            if (req.opportunityId == null || req.contactId == null) {
                throw new SoftCreditException('OpportunityId and ContactId are required on every request.');
            }
            oppIds.add(req.opportunityId);
            pairKeys.add(req.opportunityId + '_' + req.contactId);
        }

        // ─── SOQL 1: Load opportunities for validation ───
        Map<Id, Opportunity> oppMap = new Map<Id, Opportunity>();
        for (Opportunity opp : [
            SELECT Id, Amount, npsp__Primary_Contact__c
            FROM Opportunity
            WHERE Id IN :oppIds
        ]) {
            oppMap.put(opp.Id, opp);
        }

        // ─── Validation (before any DML) ───
        for (SoftCreditRequest req : requests) {
            Opportunity opp = oppMap.get(req.opportunityId);
            if (opp == null) {
                throw new SoftCreditException('Opportunity not found: ' + req.opportunityId);
            }
            if (req.amount == null || req.amount <= 0) {
                throw new SoftCreditException('Amount must be a positive value. Contact: ' + req.contactId);
            }
            if (opp.Amount != null && req.amount > opp.Amount) {
                throw new SoftCreditException(
                    'Soft credit amount (' + req.amount + ') exceeds opportunity amount (' + opp.Amount + ').'
                );
            }
            if (req.contactId == opp.npsp__Primary_Contact__c) {
                throw new SoftCreditException('Contact is the primary contact of the opportunity and cannot receive a soft credit.');
            }
        }

        // ─── SOQL 2: Load existing OpportunityContactRoles ───
        Map<String, OpportunityContactRole> ocrMap = new Map<String, OpportunityContactRole>();
        for (OpportunityContactRole ocr : [
            SELECT Id, OpportunityId, ContactId, Role
            FROM OpportunityContactRole
            WHERE OpportunityId IN :oppIds
        ]) {
            String key = ocr.OpportunityId + '_' + ocr.ContactId;
            if (pairKeys.contains(key) && !ocrMap.containsKey(key)) {
                ocrMap.put(key, ocr);
            }
        }

        // ─── SOQL 3: Load existing Partial Soft Credits ───
        Map<String, npsp__Partial_Soft_Credit__c> pscMap = new Map<String, npsp__Partial_Soft_Credit__c>();
        for (npsp__Partial_Soft_Credit__c psc : [
            SELECT Id,
                   npsp__Opportunity__c,
                   npsp__Related_Record__c,
                   npsp__Opportunity_Contact_Role__c,
                   npsp__Amount__c,
                   npsp__Role__c
            FROM npsp__Partial_Soft_Credit__c
            WHERE npsp__Opportunity__c IN :oppIds
        ]) {
            String key = psc.npsp__Opportunity__c + '_' + psc.npsp__Related_Record__c;
            if (pairKeys.contains(key) && !pscMap.containsKey(key)) {
                pscMap.put(key, psc);
            }
        }

        // ─── Phase 1: Determine OCR actions ───
        List<OpportunityContactRole> newOcrs = new List<OpportunityContactRole>();
        List<OpportunityContactRole> updatedOcrs = new List<OpportunityContactRole>();
        Map<Integer, OpportunityContactRole> reqOcrMap = new Map<Integer, OpportunityContactRole>();

        for (Integer i = 0; i < requests.size(); i++) {
            SoftCreditRequest req = requests.get(i);
            String key = req.opportunityId + '_' + req.contactId;

            OpportunityContactRole existingOcr = ocrMap.get(key);
            if (existingOcr != null) {
                reqOcrMap.put(i, existingOcr);
                if (existingOcr.Role != req.role) {
                    existingOcr.Role = req.role;
                    updatedOcrs.add(existingOcr);
                }
            } else {
                OpportunityContactRole newOcr = new OpportunityContactRole(
                    OpportunityId = req.opportunityId,
                    ContactId = req.contactId,
                    Role = req.role,
                    IsPrimary = false
                );
                newOcrs.add(newOcr);
                reqOcrMap.put(i, newOcr);
            }
        }

        // ─── DML 1: Insert new OpportunityContactRoles ───
        if (!newOcrs.isEmpty()) {
            insert newOcrs;
        }

        // ─── DML 2: Update existing OpportunityContactRoles (role change) ───
        if (!updatedOcrs.isEmpty()) {
            update updatedOcrs;
        }

        // ─── Phase 2: Build Partial Soft Credit records (all OCRs now have IDs) ───
        List<npsp__Partial_Soft_Credit__c> newPscs = new List<npsp__Partial_Soft_Credit__c>();
        List<npsp__Partial_Soft_Credit__c> updatedPscs = new List<npsp__Partial_Soft_Credit__c>();

        for (Integer i = 0; i < requests.size(); i++) {
            SoftCreditRequest req = requests.get(i);
            String key = req.opportunityId + '_' + req.contactId;
            OpportunityContactRole ocr = reqOcrMap.get(i);

            npsp__Partial_Soft_Credit__c existingPsc = pscMap.get(key);
            if (existingPsc != null) {
                existingPsc.npsp__Amount__c = req.amount;
                existingPsc.npsp__Role__c = req.role;
                existingPsc.npsp__Opportunity_Contact_Role__c = ocr.Id;
                updatedPscs.add(existingPsc);
            } else {
                npsp__Partial_Soft_Credit__c newPsc = new npsp__Partial_Soft_Credit__c(
                    npsp__Opportunity__c = req.opportunityId,
                    npsp__Related_Record__c = req.contactId,
                    npsp__Opportunity_Contact_Role__c = ocr.Id,
                    npsp__Amount__c = req.amount,
                    npsp__Role__c = req.role
                );
                newPscs.add(newPsc);
            }
        }

        // ─── DML 3: Insert new Partial Soft Credits ───
        if (!newPscs.isEmpty()) {
            insert newPscs;
        }

        // ─── DML 4: Update existing Partial Soft Credits ───
        if (!updatedPscs.isEmpty()) {
            update updatedPscs;
        }
    }
}
```

**Design notes:**

| Resource | Max used (200 requests) |
|----------|------------------------|
| SOQL queries | 3 (Opportunities, OCRs, Partial Soft Credits) |
