 * (ContactA = parent, ContactB = child, Type = Son/Daughter/Child).
 *
 * Re-running is safe: pairs that already have a relationship in either direction
 * are skipped.
 *
 * Governor-limit budget for 200 pairs: 1 SOQL + 1 DML.
 */
public class FamilyService {

    /**
     * Parent relationship-type record Id in the target org.
     * In production, store this in a Custom Setting or Custom Label so it can be
     * maintained without a deploy.  Replace the placeholder with the real Id.
     */
    private static final String PARENT_TYPE_ID = 'a0XX00000000000';

    /**
     * Creates Parent relationships for the supplied child→parent pairs.
     *
     * @param parentIdByChildId  Key = child Contact Id, Value = parent Contact Id.
     *                           Null or empty map is a no-op.
     */
    public static void linkParents(Map<Id, Id> parentIdByChildId) {
        if (parentIdByChildId == null || parentIdByChildId.isEmpty()) {
            return;
        }

        // ── Collect the set of every contact involved (drop nulls) ──────────
        Set<Id> allContactIds = new Set<Id>();
        for (Id childId : parentIdByChildId.keySet()) {
            Id parentId = parentIdByChildId.get(childId);
            if (childId != null)  allContactIds.add(childId);
            if (parentId != null) allContactIds.add(parentId);
        }
        allContactIds.remove(null);
        if (allContactIds.isEmpty()) {
            return;
        }

        // ── SOQL 1 of 1: existing relationships touching any of these contacts ─
        Set<String> existingKeys = new Set<String>();
        for (HEDA__Relationship__c rel : [
            SELECT HEDA__ContactA__c, HEDA__ContactB__c
            FROM   HEDA__Relationship__c
            WHERE  HEDA__ContactA__c IN :allContactIds
                OR HEDA__ContactB__c IN :allContactIds
        ]) {
            if (rel.HEDA__ContactA__c != null && rel.HEDA__ContactB__c != null) {
                existingKeys.add(pairKey(rel.HEDA__ContactA__c, rel.HEDA__ContactB__c));
            }
        }

        // ── Build the insert list (one record per new pair) ─────────────────
        List<HEDA__Relationship__c> toInsert = new List<HEDA__Relationship__c>();

        for (Id childId : parentIdByChildId.keySet()) {
            Id parentId = parentIdByChildId.get(childId);
            if (childId == null || parentId == null) {
                continue;
            }

            // Skip if a relationship already exists in either direction
            // (covers both the DB check and intra-batch deduplication)
            if (existingKeys.contains(pairKey(childId, parentId))
                || existingKeys.contains(pairKey(parentId, childId))) {
                continue;
            }

            toInsert.add(new HEDA__Relationship__c(
                HEDA__ContactA__c         = childId,
                HEDA__ContactB__c         = parentId,
                HEDA__RelationshipType__c = PARENT_TYPE_ID,
                HEDA__Status__c           = 'Current'
            ));

            // Mark both directions so a later entry in the same batch
            // (e.g. the same two contacts reversed) is also skipped.
            existingKeys.add(pairKey(childId, parentId));
            existingKeys.add(pairKey(parentId, childId));
        }

        // ── DML 1 of 1 ───────────────────────────────────────────────────────
        if (!toInsert.isEmpty()) {
            insert toInsert;
        }
    }

    /**
     * Directional pair key used for O(1) Set membership checks.
     * "child|parent" ≠ "parent|child", so both directions must be tested.
     */
    private static String pairKey(Id a, Id b) {
        return a + '|' + b;
    }
}
