public class OPP_MajorGiftFollowUp_TDTM extends TriggerHandler {

    private static final String STAGE_CLOSED_WON = 'Closed Won';
    private static final Decimal THRESHOLD_AMOUNT = 5000;

    public override void execute(Map<Id, SObject> newMap, Map<Id, SObject> oldMap) {
        List<Task> tasks = new List<Task>();

        for (Id oppId : newMap.keySet()) {
            Opportunity newOpp = (Opportunity) newMap.get(oppId);
            Opportunity oldOpp = (oldMap != null) ? (Opportunity) oldMap.get(oppId) : null;

            if (shouldCreateTask(newOpp, oldOpp)) {
                tasks.add(buildTask(newOpp));
            }
        }

        if (!tasks.isEmpty()) {
            insert tasks;
        }
    }

    private static Boolean shouldCreateTask(Opportunity newOpp, Opportunity oldOpp) {
        if (!isQualified(newOpp)) {
            return false;
        }
        // On insert (oldOpp is null) the record is newly qualified.
        // On update, only create a task if it was NOT already qualified before.
        return oldOpp == null || !isQualified(oldOpp);
    }

    private static Boolean isQualified(Opportunity opp) {
        return opp.StageName == STAGE_CLOSED_WON
            && opp.Amount != null
            && opp.Amount >= THRESHOLD_AMOUNT;
